import { queryOneData, queryTwoData } from '@/api/xcnanr/statisticalAnalysis';
import PieChart from '@/views/xcnanr/statisticalAnalysis/indexChart/echarts/PieChart';
import DoubleBarChart from '@/views/xcnanr/statisticalAnalysis/indexChart/echarts/DoubleBarChart';
import ThreeBarChart from '@/views/xcnanr/statisticalAnalysis/indexChart/echarts/ThreeBarChart';
import Pie3DChart from '@/views/xcnanr/statisticalAnalysis/indexChart/echarts/Pie3DChart';
import StackBarChart from '@/views/xcnanr/statisticalAnalysis/indexChart/echarts/StackBarChart';
import RoseChart from '@/views/xcnanr/statisticalAnalysis/indexChart/echarts/RoseChart';
export default {
  name: 'StatisticalAnalysis',
  components: {
    queryOneData: queryOneData,
    queryTwoData: queryTwoData,
    PieChart: PieChart,
    DoubleBarChart: DoubleBarChart,
    ThreeBarChart: ThreeBarChart,
    Pie3DChart: Pie3DChart,
    StackBarChart: StackBarChart,
    RoseChart: RoseChart
  },
  data: function data() {
    return {
      activeName: '1',
      cycleDateValue: '4',
      statistics: {
        planCount: 0,
        warningCount: 0,
        workOrdernCount: 0,
        chart1: {
          seriesData: [{
            name: '故障工单占比',
            value: ''
          }, {
            name: '无故障工单占比',
            value: '0'
          }],
          ratioData: ''
        },
        chart2: {
          seriesData: [{
            name: '超时工单占比',
            value: ''
          }, {
            name: '未超时工单占比',
            value: '0'
          }],
          ratioData: ''
        },
        chart3: {
          seriesData: [{
            name: '计划工单占比',
            value: ''
          }, {
            name: '未关联计划工单占比',
            value: '0'
          }],
          ratioData: ''
        },
        chart4: {
          seriesData: [{
            name: '完成工单占比',
            value: ''
          }, {
            name: '未完成工单占比',
            value: '0'
          }],
          date: '较前一日',
          countData: '',
          completeData: ''
        },
        chart5: {
          xAxisData: [],
          seriesData: [],
          seriesData2: []
        },
        chart6: {
          xAxisData: [],
          seriesData: [],
          seriesData2: [],
          seriesData3: []
        },
        chart7: {
          xAxisData: [],
          seriesData: '',
          seriesData2: '',
          seriesData3: ''
        },
        chart8: {
          xAxisData: [],
          seriesData: [],
          seriesData2: [],
          seriesData3: []
        },
        chart9: {
          xAxisData: [],
          seriesData: []
        }
      }
    };
  },
  // watch: {
  //   activeName: {
  //     handler(newValue, oldValue) {
  //       console.log(newValue, 'newValue++++++');
  //       console.log(oldValue, 'oldValue+++++++');
  //     },
  //     deep: true,
  //     // immediate: true
  //   }
  // },
  created: function created() {
    this.initUpChartData();
  },
  methods: {
    statisticsDate: function statisticsDate(data) {
      this.cycleDateValue = data;
      if (data === '2') {
        this.statistics.chart3.date = '较前一周';
      } else if (data === '3') {
        this.statistics.chart3.date = '较前一月';
      } else if (data === '4') {
        this.statistics.chart3.date = '较前一年';
      }
      this.initUpChartData();
    },
    initUpChartData: function initUpChartData() {
      var _this = this;
      queryOneData({
        cycleDate: this.cycleDateValue
      }).then(function (res) {
        console.log(res.data, '上半部分--------');
        // 1.总数（计划总数、告警总数、工单总数）
        _this.statistics.planCount = res.data.jihuaCount;
        _this.statistics.warningCount = res.data.warningCount;
        _this.statistics.workOrdernCount = res.data.gongdanCount;
        // 2.工作任务指标（巡视故障率、检修超时率、检修计划率、维修完成率）
        _this.statistics.chart1.seriesData = [{
          name: '故障率占比',
          value: res.data.inspWorkRate
        }, {
          name: '未超时工单',
          value: 100 - res.data.inspWorkRate
        }];
        _this.statistics.chart1.ratioData = res.data.workerPreviUpOrDown;
        _this.statistics.chart2.seriesData = [{
          name: '超时工单占比',
          value: res.data.repairChaoshiRate
        }, {
          name: '未超时工单占比',
          value: 100 - res.data.repairChaoshiRate
        }];
        _this.statistics.chart2.ratioData = res.data.repairPreviRateUpOrDown;
        _this.statistics.chart3.seriesData = [{
          name: '计划工单占比',
          value: res.data.planIdCountRate
        }, {
          name: '未关联计划工单占比',
          value: 100 - res.data.planIdCountRate
        }];
        _this.statistics.chart3.ratioData = res.data.planIdCountPreviUpOrDown;
        _this.statistics.chart4.seriesData = [{
          name: '超时工单占比',
          value: res.data.mainCompleRate
        }, {
          name: '未超时工单占比',
          value: 100 - res.data.mainCompleRate
        }];
        _this.statistics.chart4.countData = res.data.mainpreviCount;
        _this.statistics.chart4.completeData = res.data.mainpreviCompleCount;
      });
      queryTwoData({
        cycleDate: this.cycleDateValue
      }).then(function (res) {
        console.log(res.data, '下半部分--------');
        // 3.区域作业统计（作业计划、作业工单）
        _this.statistics.chart5.seriesData = res.data.productPlanBar.inspectPlanList;
        _this.statistics.chart5.seriesData2 = res.data.productPlanBar.repairPlanList;
        _this.statistics.chart6.seriesData = res.data.productOrderBar.inspectOrderList;
        _this.statistics.chart6.seriesData2 = res.data.productOrderBar.repairList;
        _this.statistics.chart6.seriesData3 = res.data.productOrderBar.maintanceList;
        // 4.工单类型分布
        _this.statistics.chart7.seriesData = res.data.proTypePie.infoMaintanceRate;
        _this.statistics.chart7.seriesData2 = res.data.proTypePie.insWorkerRate;
        _this.statistics.chart7.seriesData3 = res.data.proTypePie.infoRepairRate;
        // 5.检修类别统计
        _this.statistics.chart8.seriesData = res.data.repairCiModeBar;
        // 6.工作类别分布
        _this.statistics.chart9.seriesData = res.data.jobCategoryPie;
      });
    }
  }
};
